# 8. Land cover and elevation from Microsoft Planetary Computer
import pystac_client, planetary_computer
CAT = pystac_client.Client.open("https://planetarycomputer.microsoft.com/api/stac/v1",
                                modifier=planetary_computer.sign_inplace)
BBOX = [minx, miny, maxx, maxy]

wc_items = list(CAT.search(collections=["esa-worldcover"], bbox=BBOX).items())
v2 = [it for it in wc_items if str(it.properties.get("esa_worldcover:product_version", "")).startswith("2")]
wc_items = v2 or wc_items
WC = np.zeros((H, W), dtype=np.uint8)
for k, it in enumerate(wc_items, 1):
    paint(it.assets["map"].href, WC, Resampling.nearest)
    print(f"  land cover tile {k}/{len(wc_items)}", end="\r")
FR, NODATA_HEX = wc_fractions(LABELS, WC, N)
print(f"Land cover: {len(wc_items)} tiles; {NODATA_HEX} hexes had no land data and count as water (usually sea).")

dem_items = list(CAT.search(collections=["cop-dem-glo-30"], bbox=BBOX).items())
DEM = np.full((H, W), np.nan, dtype=np.float32)
for k, it in enumerate(dem_items, 1):
    paint(it.assets["data"].href, DEM, Resampling.average)
    print(f"  elevation tile {k}/{len(dem_items)}", end="\r")
# Average elevation over land pixels only, so a coastal hex is not pulled down by the sea beside it
elev_land, miss_land = hex_means(LABELS, DEM, N, valid_mask=(WC != 80))
elev_all, miss_all = hex_means(LABELS, DEM, N)
elev = np.where(~miss_land, elev_land, elev_all)
elev_missing = miss_land & miss_all
sea = elev_missing & (FR["water"] >= 0.99)
elev[sea] = 0.0
elev_missing &= ~sea
ELEV = fill_missing(elev, nb, elev_missing)
print(f"Elevation: {len(dem_items)} tiles; range {np.nanmin(ELEV):.0f} to {np.nanmax(ELEV):.0f} m.")

# ---- 9. Population from WorldPop (country file, 2020, 1 km)
# 9. Population from WorldPop (country file, 2020, 1 km)
POP = None
POP_SOURCE = None
POP_PATH = None
try:
    ISO3 = pycountry.countries.get(alpha_2=CC).alpha_3 if CC else None
except Exception:
    ISO3 = None
if ISO3:
    urls = [f"https://data.worldpop.org/GIS/Population/Global_2000_2020_1km_UNadj/2020/{ISO3}/{ISO3.lower()}_ppp_2020_1km_Aggregated_UNadj.tif",
            f"https://data.worldpop.org/GIS/Population/Global_2000_2020_1km/2020/{ISO3}/{ISO3.lower()}_ppp_2020_1km_Aggregated.tif"]
    for url in urls:
        try:
            path = f"/content/{ISO3.lower()}_pop.tif" if os.path.isdir("/content") else f"{ISO3.lower()}_pop.tif"
            if not os.path.exists(path):
                with requests.get(url, stream=True, timeout=300, headers=HEADERS) as r:
                    r.raise_for_status()
                    with open(path, "wb") as f:
                        for chunk in r.iter_content(1 << 20):
                            f.write(chunk)
            with rasterio.open(path) as src:
                sb = src.bounds
                ib = (max(minx, sb.left), max(miny, sb.bottom), min(maxx, sb.right), min(maxy, sb.top))
                if ib[0] >= ib[2] or ib[1] >= ib[3]:
                    raise ValueError("population file does not cover the region")
                win = window_from_bounds(*ib, transform=src.transform).round_offsets().round_lengths()
                arr = src.read(1, window=win).astype(float)
                if src.nodata is not None:
                    arr[arr == src.nodata] = 0
                arr[~np.isfinite(arr) | (arr < 0)] = 0
                wt = src.window_transform(win)
            target_dx = (maxx - minx) / W
            if target_dx < abs(wt.a):
                xs = minx + (np.arange(W) + 0.5) * target_dx
                ys = maxy - (np.arange(H) + 0.5) * (maxy - miny) / H
                ncol = np.floor((xs - wt.c) / wt.a).astype(np.int64)
                nrow = np.floor((ys - wt.f) / wt.e).astype(np.int64)
                vc = (ncol >= 0) & (ncol < arr.shape[1]); vr = (nrow >= 0) & (nrow < arr.shape[0])
                cnt = arr[np.clip(nrow, 0, arr.shape[0] - 1)][:, np.clip(ncol, 0, arr.shape[1] - 1)]
                parent = nrow[:, None] * arr.shape[1] + ncol[None, :]
                valid = vr[:, None] & vc[None, :]
                cnt = np.where(valid, cnt, 0.0); parent = np.where(valid, parent, -1)
                POP = pop_to_hexes(LABELS, WC == 50, cnt, parent, N)
            else:
                rr, cc_ = np.mgrid[0:arr.shape[0], 0:arr.shape[1]]
                xs = wt.c + (cc_ + 0.5) * wt.a; ys = wt.f + (rr + 0.5) * wt.e
                tc = np.floor((xs - minx) / target_dx).astype(np.int64)
                tr = np.floor((maxy - ys) / ((maxy - miny) / H)).astype(np.int64)
                ok = (tc >= 0) & (tc < W) & (tr >= 0) & (tr < H) & (arr > 0)
                lab = LABELS[tr[ok], tc[ok]]
                keep = lab >= 0
                POP = np.bincount(lab[keep], weights=arr[ok][keep], minlength=N)
            POP_SOURCE = url
            POP_PATH = path
            break
        except Exception as e:
            print(f"Could not use {url.rsplit('/', 1)[-1]}: {e}")
if POP is None:
    POP = FR["built"] * area * 3000.0
    NOTES.append("WorldPop could not be downloaded, so population is estimated at 3,000 people per km2 of built-up land.")
    print("Population: estimated from built-up land.")
else:
    NOTES.append(f"Population covers {pycountry.countries.get(alpha_3=ISO3).name} only. Surrounding land in other countries counts as empty.")
    print(f"Population: about {POP.sum():,.0f} people in the region.")

# ---- 10. Rivers, canals and streams from OpenStreetMap (narrow ones do not show in satellite land cover)
# 10. Rivers, canals and streams from OpenStreetMap (narrow ones do not show in satellite land cover)
RIVER = np.zeros(N)
RIVERS_OK = False
try:
    kinds = "river|canal" if region_km.area > 20000 else "river|canal|stream"
    query = f'[out:json][timeout:180];way["waterway"~"^({kinds})$"]({miny},{minx},{maxy},{maxx});out geom;'
    import time
    SERVERS = ["https://overpass-api.de/api/interpreter",
               "https://overpass.kumi.systems/api/interpreter",
               "https://maps.mail.ru/osm/tools/overpass/api/interpreter",
               "https://overpass.private.coffee/api/interpreter"]
    data, last_err = None, None
    for attempt in range(3):
        for url in SERVERS:
            host = url.split("/")[2]
            try:
                print(f"  asking {host} for waterways...")
                r = requests.post(url, data={"data": query}, headers=HEADERS, timeout=200)
                if r.status_code in (429, 502, 503, 504):
                    raise RuntimeError(f"server busy ({r.status_code})")
                r.raise_for_status()
                data = r.json()
                break
            except Exception as e:
                last_err = e
                print(f"  {host} did not answer: {e}")
        if data is not None:
            break
        if attempt < 2:
            print(f"  all servers busy; waiting {45 * (attempt + 1)} seconds and trying again...")
            time.sleep(45 * (attempt + 1))
    if data is None:
        raise RuntimeError(f"no waterway server answered ({last_err})")
    ways = [(el.get("tags", {}).get("waterway"), [(p["lat"], p["lon"]) for p in el.get("geometry", [])])
            for el in data.get("elements", []) if el.get("type") == "way"]
    RIVER = waterway_hexes(ways, lambda la, lo: h3.latlng_to_cell(la, lo, RES), IDX, EDGE_KM / 2)
    RIVERS_OK = True
    print(f"Waterways: {len(ways)} mapped lines cross {int((RIVER > 0).sum())} hexes.")
except Exception as e:
    NOTES.append("Mapped rivers and canals could not be downloaded, so only water visible from space counts.")
    print("Could not get waterways from OpenStreetMap:", e)

# ---- 11. Regional threads: the river basin upstream of the city and the foodshed around it
# 11. Regional threads: the river basin upstream of the city and the foodshed around it
from collections import defaultdict, deque
REGIONAL = None
FOOD_RADII_KM = [50, 100, 250]
WC_LETTER = {10: "t", 20: "s", 30: "g", 40: "c", 50: "b", 60: "n", 70: "n", 80: "w", 90: "e", 95: "e", 100: "g"}
try:
    # Where the city's people are: the population-weighted center of its own built-up hexes
    w_urb = POP * (FR["built"] >= 0.25) * inside
    if w_urb.sum() <= 0:
        w_urb = POP * (FR["built"] >= 0.25)
    if w_urb.sum() > 0:
        CLAT, CLNG = float(np.average(lat, weights=w_urb)), float(np.average(lng, weights=w_urb))
    else:
        CLAT, CLNG = float(PLACE_GEOM.centroid.y), float(PLACE_GEOM.centroid.x)
    reg_notes = []

    # Water thread: every river basin that drains toward the city (HydroBASINS level 8)
    BASIN = None
    try:
        import geopandas as gpd
        if CLNG < -30:
            cands = ["ar", "na"] if CLAT > 60 else (["sa", "na"] if (CLAT < 12 and CLNG > -82) else ["na", "sa"])
        elif CLNG < 60:
            cands = ["eu", "af", "si"] if CLAT >= 35 else ["af", "eu", "as"]
        else:
            cands = ["si", "as"] if CLAT > 55 else (["au", "as"] if (CLAT < -10 and CLNG > 110) else ["as", "au", "si"])
        pt = Point(CLNG, CLAT)
        gdf, start = None, None
        for code in cands:
            zpath = f"/content/hybas_{code}_lev08_v1c.zip" if os.path.isdir("/content") else f"hybas_{code}_lev08_v1c.zip"
            if not os.path.exists(zpath):
                url = f"https://data.hydrosheds.org/file/hydrobasins/standard/hybas_{code}_lev08_v1c.zip"
                print(f"  downloading river basins ({code})...")
                with requests.get(url, stream=True, timeout=600, headers=HEADERS) as r:
                    r.raise_for_status()
                    with open(zpath, "wb") as f:
                        for chunk in r.iter_content(1 << 20):
                            f.write(chunk)
            g = gpd.read_file(f"zip://{zpath}")
            hit = g[g.contains(pt)]
            if len(hit) == 0:
                near = g.distance(pt)
                if near.min() < 0.05:
                    hit = g.loc[[near.idxmin()]]
            if len(hit):
                gdf, start = g, int(hit.iloc[0]["HYBAS_ID"])
                break
        if gdf is None:
            raise RuntimeError("no basin found at the city center")
        ups = defaultdict(list)
        for hid, nd in zip(gdf["HYBAS_ID"].astype("int64"), gdf["NEXT_DOWN"].astype("int64")):
            ups[int(nd)].append(int(hid))
        ids, q = {start}, deque([start])
        while q:
            a = q.popleft()
            for b in ups.get(a, []):
                if b not in ids:
                    ids.add(b)
                    q.append(b)
        sel = gdf[gdf["HYBAS_ID"].astype("int64").isin(ids)]
        bgeom = unary_union(list(sel.geometry)).buffer(0)
        BASIN = {"geom": bgeom, "area_km2": float(sel["SUB_AREA"].sum()), "n": int(len(sel))}
        print(f"Water thread: {len(sel)} sub-basins drain toward the city, about {BASIN['area_km2']:,.0f} km2.")
    except Exception as e:
        reg_notes.append("The upstream river basin could not be loaded, so the water thread is missing.")
        print("Could not build the water thread:", e)

    # Area for the regional view: the 250 km foodshed circle, widened to hold the whole basin
    R = max(FOOD_RADII_KM)
    kxc = 111.32 * math.cos(math.radians(CLAT))
    ex = [CLNG - R / kxc, CLAT - R / 110.57, CLNG + R / kxc, CLAT + R / 110.57]
    if BASIN is not None:
        b = BASIN["geom"].bounds
        ex = [min(ex[0], b[0]), min(ex[1], b[1]), max(ex[2], b[2]), max(ex[3], b[3])]
    ex = [max(-180, ex[0]), max(-85, ex[1]), min(180, ex[2]), min(85, ex[3])]
    GRID, GTR, _ = coarse_landcover(tuple(ex), npx=260)
    gh, gw = GRID.shape
    xs = ex[0] + (np.arange(gw) + 0.5) * (ex[2] - ex[0]) / gw
    ys = ex[3] - (np.arange(gh) + 0.5) * (ex[3] - ex[1]) / gh
    XX, YY = np.meshgrid(xs, ys)
    DKM = np.hypot((XX - CLNG) * 111.32 * np.cos(np.radians(YY)), (YY - CLAT) * 110.57)
    PXA = ((ex[2] - ex[0]) / gw * 111.32 * np.cos(np.radians(YY))) * ((ex[3] - ex[1]) / gh * 110.57)

    # Food thread: cropland and people within each distance
    food = []
    pop_ok = False
    pop_dist, pop_vals = None, None
    if POP_PATH:
        try:
            with rasterio.open(POP_PATH) as src:
                sb = src.bounds
                ib = (max(ex[0], sb.left), max(ex[1], sb.bottom), min(ex[2], sb.right), min(ex[3], sb.top))
                if ib[0] < ib[2] and ib[1] < ib[3]:
                    win = window_from_bounds(*ib, transform=src.transform).round_offsets().round_lengths()
                    arr = src.read(1, window=win).astype(float)
                    if src.nodata is not None:
                        arr[arr == src.nodata] = 0
                    arr[~np.isfinite(arr) | (arr < 0)] = 0
                    wt = src.window_transform(win)
                    rr, cc_ = np.mgrid[0:arr.shape[0], 0:arr.shape[1]]
                    px = wt.c + (cc_ + 0.5) * wt.a
                    py = wt.f + (rr + 0.5) * wt.e
                    pop_dist = np.hypot((px - CLNG) * 111.32 * np.cos(np.radians(py)), (py - CLAT) * 110.57)
                    pop_vals = arr
                    pop_ok = True
        except Exception as e:
            print("Could not read regional population:", e)
    if not pop_ok:
        reg_notes.append("Regional population was not available, so the foodshed shows cropland only.")
    for rk in FOOD_RADII_KM:
        m = DKM <= rk
        crop = float((PXA[m & (GRID == 40)]).sum())
        people = float(pop_vals[pop_dist <= rk].sum()) if pop_ok else None
        food.append({"km": rk, "crop_km2": round(crop, 1), "pop": round(people) if people is not None else None})
    reg_notes.append("Regional population counts " + (pycountry.countries.get(alpha_3=ISO3).name if ISO3 else "one country") + " only.")
    print("Food thread: " + "; ".join(f"{f['km']} km: {f['crop_km2']:,.0f} km2 cropland" + (f", {f['pop']:,} people" if f['pop'] is not None else "") for f in food))

    # Land cover shares across the basin
    basin_out = None
    if BASIN is not None:
        bmask = rio_rasterize([(BASIN["geom"], 1)], out_shape=GRID.shape, transform=GTR, fill=0, dtype="uint8").astype(bool)
        valid = bmask & (GRID > 0)
        tot = float(PXA[valid].sum()) or 1.0
        def share(codes):
            return round(float(PXA[valid & np.isin(GRID, codes)].sum()) / tot, 3)
        shares = {"forest": share([10]), "shrub_grass": share([20, 30, 100]), "cropland": share([40]),
                  "built": share([50]), "bare": share([60, 70]), "water": share([80]), "wetland": share([90, 95])}
        simp = BASIN["geom"].simplify(max(ex[2] - ex[0], ex[3] - ex[1]) / 400)
        polys = [simp] if simp.geom_type == "Polygon" else [p for p in getattr(simp, "geoms", []) if p.geom_type == "Polygon"]
        rings = []
        for p in sorted(polys, key=lambda p: p.area, reverse=True)[:20]:
            rings.append([round(v, 4) for x, y in p.exterior.coords for v in (y, x)])
        basin_out = {"area_km2": round(BASIN["area_km2"]), "subbasins": BASIN["n"], "shares": shares, "rings": rings,
                     "source": "HydroBASINS level 8 (WWF HydroSHEDS)"}

    letters = np.full(GRID.shape, ".", dtype="<U1")
    for code, ch in WC_LETTER.items():
        letters[GRID == code] = ch
    REGIONAL = {
        "center": [round(CLAT, 5), round(CLNG, 5)],
        "grid": {"bounds": [round(v, 5) for v in ex], "w": int(gw), "h": int(gh), "codes": "".join(letters.ravel())},
        "foodshed": food, "need_km2_per_person": 0.0019, "basin": basin_out, "notes": reg_notes,
    }
except Exception as e:
    print("Could not build the regional threads:", e)

# ---- 12. Flood screening, then save the place file
# 12. Flood screening, then save the place file
OPEN_WATER = FR["water"] >= 0.3
WATER = OPEN_WATER | (RIVER >= 1.0)   # rivers, lakes and sea; canals and streams are drawn but are not flood sources
REACH = max(2.0, min(2.0 * SPACING_KM, SPACING_KM + 6.0))
FLOOD, WATER_KM = flood_weights(nb, WATER, ELEV, SPACING_KM, height_m=5.0, reach_km=REACH, open_water=OPEN_WATER)
if RES <= 6:
    NOTES.append("Hexes are large, so floodplains are only roughly placed.")
if not WATER.any():
    NOTES.append("No river, lake or sea was found in the region, so flood exposure is zero.")

cells_out = {"id": HEXES, "lat": lat, "lng": lng, "area": area, "inside": inside, "pop": POP,
             "elev": ELEV, "flood": FLOOD, "water_km": WATER_KM, "nb": nb, "poly": poly, "river": RIVER}
cells_out.update(FR)
SOURCES = [
    "Outline: OpenStreetMap contributors, via Nominatim (ODbL)",
    "Land cover: ESA WorldCover 2021 v200, 10 m (CC BY 4.0), via Microsoft Planetary Computer",
    "Elevation: Copernicus DEM GLO-30, via Microsoft Planetary Computer",
    "Population: WorldPop 2020, 1 km (CC BY 4.0)" if POP_SOURCE else "Population: estimated from built-up land",
    "Hex grid: H3 (Uber, Apache 2.0)",
]
if RIVERS_OK:
    SOURCES.insert(1, "Rivers and canals: OpenStreetMap contributors, via the Overpass API (ODbL)")
place = place_dict(NAME, PLACE, hit.get("type") or hit.get("addresstype") or "place", RES, cells_out, SOURCES,
                   NOTES, datetime.date.today().isoformat())
place["display_name"] = DISPLAY
place["buffer_km"] = BUFFER_KM
if REGIONAL is not None:
    place["regional"] = REGIONAL
    SOURCES_EXTRA = ["River basins: HydroBASINS (WWF HydroSHEDS)"] if REGIONAL.get("basin") else []
    place["sources"] = place["sources"] + SOURCES_EXTRA
slug = "".join(ch if ch.isalnum() else "-" for ch in NAME.lower()).strip("-") or "place"
OUT = f"{slug}.threadlands.json"
with open(OUT, "w") as f:
    json.dump(place, f, separators=(",", ":"))
print(f"Saved {OUT} ({os.path.getsize(OUT) / 1024:,.0f} KB): {N} hexes, {POP.sum():,.0f} people.")
for note in NOTES:
    print(" -", note)
try:
    from google.colab import files
    files.download(OUT)
except Exception:
    print("Not running in Colab: the file is saved next to this notebook.")

# ---- Keep the place file even if the heat check fails
shutil.copyfile(OUT, FINAL_OUT)
print("PLACE_OK", FINAL_OUT)
PLACE_FILE = OUT
HEAT_CODE = '# 2. Core logic (the same code Threadlands is tested with)\nimport numpy as np\n\n# Landsat Collection 2 Level-2 surface temperature (ST_B10): kelvin = DN * 0.00341802 + 149.0\nST_SCALE, ST_OFFSET = 0.00341802, 149.0\n# QA_PIXEL bits: 0 fill, 1 dilated cloud, 2 cirrus, 3 cloud, 4 cloud shadow, 5 snow\nQA_BAD = (1 << 0) | (1 << 1) | (1 << 2) | (1 << 3) | (1 << 4) | (1 << 5)\n\n\ndef season_for(lat):\n    """Months to sample: the three hottest months outside the tropics, the whole year inside them."""\n    if lat >= 23.5:\n        return [6, 7, 8], "June to August"\n    if lat <= -23.5:\n        return [12, 1, 2], "December to February"\n    return list(range(1, 13)), "all year (tropical climate)"\n\n\ndef to_celsius(st_dn):\n    st = np.asarray(st_dn, dtype=float)\n    c = st * ST_SCALE + ST_OFFSET - 273.15\n    c[(st <= 0) | ~np.isfinite(st)] = np.nan\n    return c\n\n\ndef clear_mask(qa):\n    qa = np.asarray(qa).astype(np.int64)\n    return (qa & QA_BAD) == 0\n\n\ndef hex_means(hex_of_pixel, lst_c, clear, n, min_clear=0.3):\n    """Mean clear-sky temperature per hex for one scene; NaN where too little of the hex is clear."""\n    h = np.asarray(hex_of_pixel).ravel()\n    t = np.asarray(lst_c, dtype=float).ravel()\n    ok_px = h >= 0\n    tot = np.bincount(h[ok_px], minlength=n).astype(float)\n    good = ok_px & np.asarray(clear).ravel() & np.isfinite(t)\n    cnt = np.bincount(h[good], minlength=n).astype(float)\n    s = np.bincount(h[good], weights=t[good], minlength=n)\n    out = np.full(n, np.nan)\n    keep = (cnt > 0) & (cnt >= min_clear * tot)\n    out[keep] = s[keep] / cnt[keep]\n    return out\n\n\ndef combine(stack, land):\n    """Median over scenes of absolute temperature and of each scene\'s departure from its own land median.\n\n    The departure removes day-to-day weather, so scenes from different days can be pooled."""\n    stack = np.asarray(stack, dtype=float)\n    land = np.asarray(land, dtype=bool)\n    rel = np.full_like(stack, np.nan)\n    for k in range(stack.shape[0]):\n        v = stack[k][land & np.isfinite(stack[k])]\n        if len(v) >= 10:\n            rel[k] = stack[k] - np.median(v)\n    with np.errstate(all="ignore"):\n        import warnings\n        with warnings.catch_warnings():\n            warnings.simplefilter("ignore", RuntimeWarning)\n            absval = np.nanmedian(stack, axis=0)\n            relval = np.nanmedian(rel, axis=0)\n            nobs = np.sum(np.isfinite(rel), axis=0)\n    return absval, relval, nobs\n# 3. Choose your place file\nimport json, os, time, datetime\nimport numpy as np\nPLACE_FILE = PLACE_FILE   # or a path such as "milan.threadlands.json"\nif PLACE_FILE is None:\n    try:\n        from google.colab import files\n        up = files.upload()\n        PLACE_FILE = next(iter(up))\n    except ImportError:\n        raise SystemExit("Set PLACE_FILE to the path of your place file.")\nplace = json.load(open(PLACE_FILE))\nC = place["cells"]\nN, RES = len(C["id"]), place["h3_res"]\nIDX = {h: i for i, h in enumerate(C["id"])}\npts = np.concatenate([np.asarray(p, dtype=float) for p in C["poly"]])\nplat, plng = pts[0::2], pts[1::2]\nBBOX = [float(plng.min()), float(plat.min()), float(plng.max()), float(plat.max())]\nMONTHS, SEASON = season_for(float(np.median(C["lat"])))\nprint(f"{place[\'name\']}: {N:,} hexes; season used: {SEASON}")\n# 4. Find clear Landsat 8 and 9 scenes over the place\nimport pystac_client, planetary_computer\nMAX_SCENES = 20\ncat = pystac_client.Client.open("https://planetarycomputer.microsoft.com/api/stac/v1", modifier=planetary_computer.sign_inplace)\nfound = cat.search(collections=["landsat-c2-l2"], bbox=BBOX, datetime="2021-01-01/2025-12-31",\n                   query={"eo:cloud_cover": {"lt": 30}, "platform": {"in": ["landsat-8", "landsat-9"]}}, max_items=800)\nitems = [it for it in found.items() if it.datetime.month in MONTHS and "lwir11" in it.assets]\ndef overlap(it):\n    b = it.bbox\n    w = max(0.0, min(b[2], BBOX[2]) - max(b[0], BBOX[0])); h = max(0.0, min(b[3], BBOX[3]) - max(b[1], BBOX[1]))\n    return w * h / max(1e-9, (BBOX[2] - BBOX[0]) * (BBOX[3] - BBOX[1]))\nitems.sort(key=lambda it: (it.properties.get("eo:cloud_cover", 100) - 40 * overlap(it)))\nitems = items[:MAX_SCENES]\nprint(f"Using {len(items)} scenes:", ", ".join(sorted(it.datetime.strftime("%Y-%m-%d") for it in items)))\n# 5. Read each scene and average the clear pixels in every hex\nimport rasterio, h3, pyproj\nfrom rasterio.windows import from_bounds, Window\nfrom rasterio.enums import Resampling\nfrom affine import Affine\nos.environ.update({"GDAL_DISABLE_READDIR_ON_OPEN": "EMPTY_DIR", "GDAL_HTTP_MAX_RETRY": "4", "GDAL_HTTP_RETRY_DELAY": "2"})\npx_m = (place["hex_km2"] / 60) ** 0.5 * 1000          # about 60 samples per hex\nFACTOR = max(3, int(round(px_m / 30)))                   # Landsat thermal is about 100 m, so at least 90 m\nstack, used = [], []\nfor k, it in enumerate(items):\n    t0 = time.time()\n    try:\n        signed = planetary_computer.sign(it)\n        with rasterio.open(signed.assets["lwir11"].href) as src:\n            to_crs = pyproj.Transformer.from_crs("EPSG:4326", src.crs, always_xy=True)\n            xs, ys = to_crs.transform([BBOX[0], BBOX[2], BBOX[0], BBOX[2]], [BBOX[1], BBOX[1], BBOX[3], BBOX[3]])\n            win = from_bounds(min(xs), min(ys), max(xs), max(ys), src.transform)\n            win = win.intersection(Window(0, 0, src.width, src.height)).round_offsets().round_lengths()\n            oh, ow = max(1, int(win.height // FACTOR)), max(1, int(win.width // FACTOR))\n            st = src.read(1, window=win, out_shape=(oh, ow), resampling=Resampling.nearest)\n            wt = src.window_transform(win) * Affine.scale(win.width / ow, win.height / oh)\n            crs = src.crs\n        with rasterio.open(signed.assets["qa_pixel"].href) as q:\n            qa = q.read(1, window=win, out_shape=(oh, ow), resampling=Resampling.nearest)\n    except Exception as e:\n        print(f"  skipped {it.id}: {e}")\n        continue\n    lst = to_celsius(st)\n    ok = clear_mask(qa) & np.isfinite(lst)\n    rr, cc = np.mgrid[0:oh, 0:ow]\n    x = wt.c + (cc + 0.5) * wt.a\n    y = wt.f + (rr + 0.5) * wt.e\n    to_ll = pyproj.Transformer.from_crs(crs, "EPSG:4326", always_xy=True)\n    lon, la = to_ll.transform(x.ravel(), y.ravel())\n    inb = (lon >= BBOX[0]) & (lon <= BBOX[2]) & (la >= BBOX[1]) & (la <= BBOX[3])\n    hx = np.full(lon.shape, -1, dtype=np.int64)\n    for j in np.flatnonzero(inb):\n        hx[j] = IDX.get(h3.latlng_to_cell(la[j], lon[j], RES), -1)\n    means = hex_means(hx, lst, ok, N)\n    got = int(np.isfinite(means).sum())\n    if got >= max(10, 0.05 * N):\n        stack.append(means); used.append(it.datetime.strftime("%Y-%m-%d"))\n    print(f"  {k + 1}/{len(items)} {it.datetime:%Y-%m-%d}: {got:,} hexes clear ({time.time() - t0:.0f} s)")\nif not stack:\n    raise SystemExit("No clear scenes covered this place. Try again later or raise MAX_SCENES.")\nLAND = np.asarray(C["water"], dtype=float) < 0.5\nLST, LST_REL, NOBS = combine(np.vstack(stack), LAND)\nprint(f"{len(stack)} scenes used; {np.isfinite(LST_REL).sum():,} of {N:,} hexes have a reading.")\n# 6. Save the place file with the heat readings added\ndef rnd(a, d):\n    return [round(float(v), d) if np.isfinite(v) else None for v in a]\nC["lst"] = rnd(LST, 1)\nC["lst_rel"] = rnd(LST_REL, 2)\nC["lst_n"] = [int(v) for v in NOBS]\nplace["heat_check"] = {\n    "source": "Landsat 8-9 Collection 2 surface temperature (USGS/NASA), via Microsoft Planetary Computer",\n    "season": SEASON, "years": "2021-2025", "scenes": len(used), "dates": used,\n    "note": "Daytime land surface temperature, about 10:30 local time, clear skies only.",\n}\nplace["sources"] = [s for s in place.get("sources", []) if not s.startswith("Surface temperature")] +     ["Surface temperature: Landsat 8-9 Collection 2 (USGS/NASA), via Microsoft Planetary Computer"]\nstem = os.path.basename(PLACE_FILE).replace(".threadlands.json", "").replace(".json", "")\nOUT = (stem if stem.endswith("-heat") else stem + "-heat") + ".threadlands.json"\nwith open(OUT, "w") as f:\n    json.dump(place, f, separators=(",", ":"))\nprint(f"Saved {OUT}")\nb = np.asarray(C["built"], float); t = np.asarray(C["tree"], float); cr = np.asarray(C["crop"], float)\nfor name, m in [("Mostly built-up", b >= 0.5), ("Mostly tree cover", t >= 0.5), ("Mostly cropland", cr >= 0.5)]:\n    v = LST_REL[m & np.isfinite(LST_REL)]\n    if len(v):\n        print(f"  {name}: {np.median(v):+.1f} C compared with typical land ({len(v)} hexes)")\ntry:\n    from google.colab import files\n    files.download(OUT)\nexcept Exception:\n    print("Not running in Colab: the file is saved next to this notebook.")'
try:
    exec(HEAT_CODE, globals())
    shutil.copyfile(OUT, FINAL_OUT)
    print("HEAT_OK")
except BaseException as e:
    print("HEAT_FAILED:", repr(e))
    traceback.print_exc()
